head.b:skin:
/* ============================================================
   The Bank of Time — end-time watch
   Design system, layouts and responsive styles
   ============================================================ */

:root {
  --ink: #0a0f0d;
  --ink-2: #0d1511;
  --ink-3: #111b16;
  --paper: #f4eee3;
  --paper-deep: #ebe2d2;
  --ink-text: #17201a;
  --muted: #a2a69d;
  --muted-2: #646c63;
  --gold: #d7b36a;
  --gold-2: #b98f43;
  --gold-soft: #ecd8aa;
  --line: rgba(244, 238, 227, 0.13);
  --line-dark: rgba(23, 32, 26, 0.13);
  --font-display: "Fraunces", "Iowan Old Style", Georgia, serif;
  --font-body: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --container: 1180px;
  --ease: cubic-bezier(0.2, 0.7, 0.2, 1);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 110px;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
}

img,
svg {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

h1,
h2,
h3,
h4,
p,
blockquote,
figure {
  margin: 0;
}

ul,
ol {
  margin: 0;
  padding: 0;
}

::selection {
  background: var(--gold);
  color: var(--ink);
}

:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}

[hidden] {
  display: none !important;
}

.container {
  width: min(var(--container), calc(100% - 56px));
  margin-inline: auto;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: fixed;
  top: 14px;
  left: 14px;
  z-index: 500;
  transform: translateY(-180%);
  padding: 12px 18px;
  border-radius: 999px;
  background: var(--gold);
  color: var(--ink);
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  transition: transform 0.25s var(--ease);
}

.skip-link:focus {
  transform: translateY(0);
}

/* ------------------------------------------------------------
   Header & navigation
   ------------------------------------------------------------ */

.site-header {
  position: fixed;
  inset: 0 0 auto;
  z-index: 200;
  background: linear-gradient(180deg, rgba(7, 11, 9, 0.48), rgba(7, 11, 9, 0));
  border-bottom: 1px solid transparent;
  transition: background 0.35s ease, border-color 0.35s ease, backdrop-filter 0.35s ease;
}

.site-header.is-scrolled {
  background: rgba(8, 13, 10, 0.88);
  border-bottom-color: var(--line);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  height: 84px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  color: var(--paper);
  text-decoration: none;
}

.brand-mark {
  width: 38px;
  height: 38px;
  flex: none;
  color: var(--gold);
}

.brand-text {
  display: flex;
  flex-direction: column;
}

.brand-name {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 450;
  line-height: 1.1;
  letter-spacing: 0.005em;
}

.brand-sub {
  margin-top: 4px;
  font-size: 8.5px;
  font-weight: 500;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--muted);
}

.site-nav {
  display: flex;
  align-items: center;
  gap: 30px;
}

.nav-link {
  position: relative;
  padding: 8px 0;
  color: rgba(244, 238, 227, 0.7);
  font-size: 13.5px;
  letter-spacing: 0.02em;
  text-decoration: none;
  transition: color 0.25s ease;
}

.nav-link::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 1px;
  height: 1px;
  background: var(--gold);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s var(--ease);
}

.nav-link:hover,
.nav-link[aria-current="page"] {
  color: var(--paper);
}

.nav-link:hover::after,
.nav-link[aria-current="page"]::after {
  transform: scaleX(1);
}

.nav-cta {
  margin-left: 6px;
}

.nav-toggle {
  display: none;
  width: 44px;
  height: 44px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.03);
}

.nav-toggle span {
  display: block;
  width: 16px;
  height: 1.5px;
  border-radius: 2px;
  background: var(--paper);
  transition: transform 0.3s ease, opacity 0.3s ease;
}

.nav-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(6.5px) rotate(45deg);
}

.nav-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.nav-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-6.5px) rotate(-45deg);
}

/* ------------------------------------------------------------
   Buttons & shared type
   ------------------------------------------------------------ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 52px;
  padding: 0 27px;
  border: 1px solid transparent;
  border-radius: 999px;
  font-family: var(--font-body);
  font-size: 13.5px;
  font-weight: 500;
  letter-spacing: 0.025em;
  line-height: 1.2;
  text-decoration: none;
  white-space: nowrap;
  transition: transform 0.3s var(--ease), background 0.3s ease, border-color 0.3s ease, color 0.3s ease, box-shadow 0.3s ease;
}

.btn svg {
  width: 16px;
  height: 16px;
  flex: none;
  transition: transform 0.3s var(--ease);
}

.btn:hover svg {
  transform: translateX(3px);
}

.btn-gold {
  background: linear-gradient(135deg, #e8cc90, #cfa75c);
  color: #181206;
  box-shadow: 0 12px 34px -14px rgba(215, 179, 106, 0.65);
}

.btn-gold:hover {
  transform: translateY(-2px);
  box-shadow: 0 18px 40px -16px rgba(215, 179, 106, 0.8);
}

.btn-ghost {
  border-color: rgba(244, 238, 227, 0.22);
  background: rgba(255, 255, 255, 0.02);
  color: var(--paper);
}

.btn-ghost:hover {
  border-color: rgba(215, 179, 106, 0.55);
  background: rgba(215, 179, 106, 0.07);
}

.btn-dark {
  background: var(--ink);
  color: var(--paper);
  box-shadow: 0 10px 24px -16px rgba(10, 15, 13, 0.7);
}

.btn-dark:hover {
  transform: translateY(-2px);
  background: var(--ink-3);
}

.btn-outline-dark {
  border-color: rgba(23, 32, 26, 0.24);
  background: transparent;
  color: var(--ink-text);
}

.btn-outline-dark:hover {
  border-color: var(--gold-2);
  color: var(--gold-2);
}

.btn-small {
  min-height: 42px;
  padding: 0 19px;
  font-size: 12.5px;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  color: var(--gold);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.24em;
  text-transform: uppercase;
}

.eyebrow::before {
  content: "";
  width: 28px;
  height: 1px;
  background: var(--gold);
  opacity: 0.75;
}

.kicker {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 22px;
  color: var(--gold-2);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.22em;
  line-height: 1.4;
  text-transform: uppercase;
}

.kicker::before {
  content: "";
  width: 24px;
  height: 1px;
  background: currentColor;
  opacity: 0.7;
}

.section-dark .kicker,
.cta-band .kicker,
.page-hero .kicker,
.hero .kicker {
  color: var(--gold);
}

.section-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3.3rem);
  font-weight: 400;
  line-height: 1.08;
  letter-spacing: -0.028em;
}

.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(23, 32, 26, 0.25);
  color: var(--ink-text);
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-decoration: none;
  text-transform: uppercase;
  transition: color 0.25s ease, border-color 0.25s ease;
}

.link-arrow svg {
  width: 15px;
  height: 15px;
  transition: transform 0.25s var(--ease);
}

.link-arrow:hover {
  color: var(--gold-2);
  border-color: var(--gold-2);
}

.link-arrow:hover svg {
  transform: translateX(3px);
}

/* ------------------------------------------------------------
   Scroll reveal
   ------------------------------------------------------------ */

.js .reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.8s ease, transform 0.8s var(--ease);
}

.js .reveal.is-visible {
  opacity: 1;
  transform: none;
}

.js .reveal-delay-1 {
  transition-delay: 0.12s;
}

.js .reveal-delay-2 {
  transition-delay: 0.24s;
}

/* ------------------------------------------------------------
   Hero
   ------------------------------------------------------------ */

.hero {
  position: relative;
  overflow: hidden;
  padding: clamp(142px, 17vh, 188px) 0 clamp(78px, 9vh, 112px);
  background:
    radial-gradient(ellipse at 15% 20%, rgba(215, 179, 106, 0.08), transparent 45%),
    radial-gradient(ellipse at 88% 55%, rgba(54, 86, 67, 0.18), transparent 52%),
    linear-gradient(160deg, #0a0f0d 0%, #0c1310 58%, #090d0b 100%);
}

.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(rgba(244, 238, 227, 0.08) 1px, transparent 1px);
  background-size: 26px 26px;
  opacity: 0.22;
  -webkit-mask-image: radial-gradient(ellipse at 58% 42%, #000 0%, transparent 68%);
  mask-image: radial-gradient(ellipse at 58% 42%, #000 0%, transparent 68%);
}

.hero::after {
  content: "";
  position: absolute;
  inset: auto 0 0;
  height: 180px;
  pointer-events: none;
  background: linear-gradient(180deg, transparent, rgba(9, 13, 11, 0.75));
}

.hero-glow {
  position: absolute;
  top: 4%;
  right: -90px;
  width: 620px;
  height: 620px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(215, 179, 106, 0.2), rgba(215, 179, 106, 0) 65%);
  filter: blur(40px);
  pointer-events: none;
}

.hero-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(0, 0.98fr);
  align-items: center;
  gap: clamp(32px, 5vw, 64px);
}

.hero h1 {
  max-width: 10ch;
  margin: 22px 0 26px;
  font-family: var(--font-display);
  font-size: clamp(3.25rem, 7.4vw, 6rem);
  font-weight: 350;
  line-height: 0.96;
  letter-spacing: -0.04em;
  text-wrap: balance;
}

.hero h1 em {
  color: var(--gold);
  font-style: italic;
  font-weight: 340;
  text-shadow: 0 0 44px rgba(215, 179, 106, 0.18);
}

.hero-lead {
  max-width: 545px;
  color: rgba(244, 238, 227, 0.67);
  font-size: clamp(1rem, 1.25vw, 1.07rem);
  font-weight: 300;
  line-height: 1.78;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 34px;
}

.hero-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  margin-top: 38px;
  list-style: none;
  color: rgba(244, 238, 227, 0.42);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.hero-meta li + li::before {
  content: "·";
  margin: 0 12px;
  color: var(--gold);
  opacity: 0.7;
}

.hero-art {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  justify-self: center;
  width: 100%;
}

.hourglass {
  width: min(100%, 492px);
  height: auto;
  overflow: visible;
  filter: drop-shadow(0 42px 60px rgba(0, 0, 0, 0.42));
}

.clock-ring {
  transform-origin: 220px 220px;
  animation: rotate-ring 120s linear infinite;
}

.sand-top {
  animation: sand-glow 7s ease-in-out infinite;
}

.stream line {
  animation: sand-stream 1.4s linear infinite;
}

.grain {
  transform-box: fill-box;
  transform-origin: center;
  animation: grain-fall 3.4s linear infinite;
}

.g2 {
  animation-delay: 1.15s;
}

.g3 {
  animation-delay: 2.3s;
}

.art-caption {
  display: flex;
  align-items: center;
  gap: 14px;
  color: rgba(244, 238, 227, 0.42);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.3em;
  text-transform: uppercase;
}

.art-caption span {
  width: 30px;
  height: 1px;
  background: rgba(215, 179, 106, 0.4);
}

@keyframes rotate-ring {
  to {
    transform: rotate(360deg);
  }
}

@keyframes sand-glow {
  50% {
    opacity: 0.72;
  }
}

@keyframes sand-stream {
  to {
    stroke-dashoffset: -18;
  }
}

@keyframes grain-fall {
  0% {
    transform: translateY(0);
    opacity: 0;
  }
  8% {
    opacity: 1;
  }
  86% {
    opacity: 0.85;
  }
  100% {
    transform: translateY(84px);
    opacity: 0;
  }
}

/* ------------------------------------------------------------
   Verse strip
   ------------------------------------------------------------ */

.verse-strip {
  position: relative;
  z-index: 2;
  padding: 24px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: #080d0b;
}

.verse-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 18px;
  text-align: center;
}

.verse-mark {
  color: var(--gold);
  font-size: 15px;
  line-height: 1;
}

.verse-text {
  max-width: 760px;
  color: rgba(244, 238, 227, 0.76);
  font-family: var(--font-display);
  font-size: clamp(0.98rem, 1.8vw, 1.14rem);
  font-style: italic;
  line-height: 1.55;
}

.verse-ref {
  color: var(--gold);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  white-space: nowrap;
}

/* ------------------------------------------------------------
   Sections
   ------------------------------------------------------------ */

.section {
  position: relative;
  padding: clamp(80px, 10vw, 120px) 0;
}

.section-cream {
  background: var(--paper);
  color: var(--ink-text);
}

.section-dark {
  overflow: hidden;
  background:
    radial-gradient(ellipse at 82% 8%, rgba(215, 179, 106, 0.07), transparent 48%),
    linear-gradient(180deg, var(--ink-2), var(--ink));
}

.section-dark::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(rgba(244, 238, 227, 0.06) 1px, transparent 1px);
  background-size: 30px 30px;
  opacity: 0.16;
  -webkit-mask-image: linear-gradient(180deg, #000, transparent 65%);
  mask-image: linear-gradient(180deg, #000, transparent 65%);
}

.section-dark > .container {
  position: relative;
  z-index: 1;
}

/* ------------------------------------------------------------
   Message / split section
   ------------------------------------------------------------ */

.split {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  align-items: start;
  gap: clamp(38px, 7vw, 96px);
}

.split-side {
  position: sticky;
  top: 120px;
}

.split-side .section-title {
  max-width: 14ch;
}

.side-note {
  max-width: 34ch;
  margin: 24px 0 30px;
  color: var(--muted-2);
  font-size: 14px;
  line-height: 1.74;
}

.prose {
  justify-self: end;
  max-width: 640px;
}

.prose p {
  margin-bottom: 20px;
  color: #4b534b;
  font-size: 16.5px;
  line-height: 1.85;
}

.prose .lead {
  margin-bottom: 24px;
  color: #2c352d;
  font-family: var(--font-display);
  font-size: clamp(1.16rem, 2vw, 1.4rem);
  font-weight: 400;
  line-height: 1.65;
  letter-spacing: -0.01em;
}

.prose blockquote {
  margin: 32px 0;
  padding: 6px 0 6px 26px;
  border-left: 2px solid var(--gold-2);
  color: #2b332c;
  font-family: var(--font-display);
  font-size: 1.18rem;
  font-style: italic;
  line-height: 1.6;
}

.pillars {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-top: 34px;
  list-style: none;
  border-top: 1px solid var(--line-dark);
  padding-top: 22px;
}

.pillars span {
  display: block;
  margin-bottom: 10px;
  color: var(--gold-2);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.18em;
}

.pillars strong {
  display: block;
  color: var(--ink-text);
  font-family: var(--font-display);
  font-size: 1.16rem;
  font-weight: 500;
  line-height: 1.2;
}

.pillars small {
  display: block;
  margin-top: 4px;
  color: var(--muted-2);
  font-size: 11.5px;
}

/* ------------------------------------------------------------
   Library cards (home)
   ------------------------------------------------------------ */

.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 48px;
  margin-bottom: 52px;
}

.section-head .section-title {
  max-width: 18ch;
}

.section-head > p {
  max-width: 370px;
  margin-bottom: 6px;
  color: var(--muted);
  font-size: 14.5px;
  line-height: 1.75;
}

.library-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.library-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 16px;
  overflow: hidden;
  padding: clamp(26px, 3vw, 34px);
  border: 1px solid var(--line);
  border-radius: 20px;
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.012));
  color: var(--paper);
  text-decoration: none;
  transition: transform 0.35s var(--ease), border-color 0.35s ease, background 0.35s ease;
}

.library-card::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(400px 220px at 92% -10%, rgba(215, 179, 106, 0.14), transparent 70%);
  opacity: 0;
  transition: opacity 0.4s ease;
}

.library-card:hover {
  border-color: rgba(215, 179, 106, 0.36);
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.055), rgba(255, 255, 255, 0.018));
  transform: translateY(-4px);
}

.library-card:hover::after {
  opacity: 1;
}

.card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.card-num {
  color: var(--muted);
  font-size: 9.5px;
  font-weight: 500;
  letter-spacing: 0.2em;
}

.card-icon {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border: 1px solid rgba(215, 179, 106, 0.3);
  border-radius: 50%;
  color: var(--gold);
}

.card-icon svg {
  width: 20px;
  height: 20px;
}

.library-card h3 {
  margin-top: 2px;
  font-family: var(--font-display);
  font-size: clamp(1.35rem, 2.3vw, 1.72rem);
  font-weight: 400;
  line-height: 1.22;
  letter-spacing: -0.015em;
}

.library-card p {
  flex: 1;
  color: var(--muted);
  font-size: 13.5px;
  line-height: 1.7;
}

.card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 8px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
}

.card-count {
  color: rgba(244, 238, 227, 0.48);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.card-go {
  color: var(--gold);
  font-size: 18px;
  line-height: 1;
  transition: transform 0.3s var(--ease);
}

.library-card:hover .card-go {
  transform: translateX(4px);
}

.library-note {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 32px;
  color: rgba(244, 238, 227, 0.4);
  font-size: 11.5px;
  letter-spacing: 0.04em;
}

.library-note::before {
  content: "✦";
  color: var(--gold);
  font-size: 12px;
}

/* ------------------------------------------------------------
   Partner advertisement
   ------------------------------------------------------------ */

.partner-section {
  padding: clamp(80px, 10vw, 112px) 0;
  background: var(--paper);
}

.partner-card {
  position: relative;
  overflow: hidden;
  padding: clamp(30px, 5vw, 62px);
  border: 1px solid rgba(215, 179, 106, 0.24);
  border-radius: 28px;
  background:
    radial-gradient(ellipse at 90% 0%, rgba(215, 179, 106, 0.13), transparent 55%),
    linear-gradient(135deg, #0b110e 0%, #101a15 56%, #0b100d 100%);
  color: var(--paper);
  box-shadow: 0 50px 90px -60px rgba(10, 15, 13, 0.55);
}

.partner-card::before {
  content: "";
  position: absolute;
  top: -220px;
  right: -140px;
  width: 520px;
  height: 520px;
  border: 1px solid rgba(215, 179, 106, 0.14);
  border-radius: 50%;
  box-shadow:
    0 0 0 46px rgba(215, 179, 106, 0.025),
    0 0 0 96px rgba(215, 179, 106, 0.018);
  pointer-events: none;
}

.partner-card::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(rgba(244, 238, 227, 0.07) 1px, transparent 1px);
  background-size: 28px 28px;
  opacity: 0.14;
  -webkit-mask-image: radial-gradient(ellipse at 82% 20%, #000, transparent 58%);
  mask-image: radial-gradient(ellipse at 82% 20%, #000, transparent 58%);
}

.partner-head,
.partner-grid {
  position: relative;
  z-index: 1;
}

.partner-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 42px;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--line);
}

.ad-label {
  display: inline-block;
  padding: 7px 12px;
  border: 1px solid rgba(244, 238, 227, 0.14);
  border-radius: 999px;
  color: rgba(244, 238, 227, 0.44);
  font-size: 8.5px;
  font-weight: 500;
  letter-spacing: 0.22em;
  line-height: 1;
  text-transform: uppercase;
}

.dlife-brand {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.dlife-mark {
  color: var(--paper);
  font-family: var(--font-display);
  font-size: 1.65rem;
  font-weight: 450;
  line-height: 1;
  letter-spacing: -0.035em;
}

.dlife-mark span {
  color: var(--gold);
}

.dlife-sub {
  margin-top: 5px;
  color: rgba(244, 238, 227, 0.42);
  font-size: 7.5px;
  font-weight: 500;
  letter-spacing: 0.19em;
  text-transform: uppercase;
}

.partner-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  align-items: start;
  gap: clamp(30px, 5vw, 64px);
}

.partner-grid h2 {
  font-family: var(--font-display);
  font-size: clamp(2.35rem, 4.6vw, 3.9rem);
  font-weight: 350;
  line-height: 1.02;
  letter-spacing: -0.035em;
}

.partner-grid h2 em {
  color: var(--gold);
  font-style: italic;
  font-weight: 340;
}

.partner-name {
  margin-bottom: 16px;
  color: var(--gold);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.partner-copy > p:not(.partner-name):not(.partner-note) {
  max-width: 48ch;
  color: rgba(244, 238, 227, 0.66);
  font-size: 14.5px;
  line-height: 1.78;
}

.partner-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 24px 0 30px;
}

.partner-tags span {
  padding: 7px 12px;
  border: 1px solid rgba(244, 238, 227, 0.14);
  border-radius: 999px;
  color: rgba(244, 238, 227, 0.68);
  font-size: 10.5px;
}

.partner-note {
  margin-top: 16px;
  color: rgba(244, 238, 227, 0.4);
  font-size: 10.5px;
  letter-spacing: 0.03em;
}

/* ------------------------------------------------------------
   Contact call-to-action band
   ------------------------------------------------------------ */

.cta-band {
  position: relative;
  overflow: hidden;
  padding: clamp(84px, 10vw, 118px) 0;
  border-top: 1px solid var(--line);
  background:
    radial-gradient(ellipse at 50% 0%, rgba(215, 179, 106, 0.13), transparent 58%),
    radial-gradient(ellipse at 8% 100%, rgba(48, 78, 61, 0.16), transparent 48%),
    var(--ink-2);
}

.cta-band::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(rgba(244, 238, 227, 0.07) 1px, transparent 1px);
  background-size: 32px 32px;
  opacity: 0.12;
  -webkit-mask-image: radial-gradient(ellipse at 50% 30%, #000, transparent 65%);
  mask-image: radial-gradient(ellipse at 50% 30%, #000, transparent 65%);
}

.cta-inner {
  position: relative;
  z-index: 1;
  text-align: center;
}

.cta-band h2 {
  max-width: 21ch;
  margin: 0 auto 20px;
  font-family: var(--font-display);
  font-size: clamp(2.1rem, 4.6vw, 3.65rem);
  font-weight: 380;
  line-height: 1.08;
  letter-spacing: -0.03em;
}

.cta-band h2 em {
  color: var(--gold);
  font-style: italic;
  font-weight: 340;
}

.cta-band p:not(.kicker) {
  max-width: 540px;
  margin: 0 auto 34px;
  color: rgba(244, 238, 227, 0.58);
  font-size: 14.5px;
  line-height: 1.78;
}

.cta-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12px;
}

/* ------------------------------------------------------------
   Footer
   ------------------------------------------------------------ */

.site-footer {
  padding: clamp(62px, 8vw, 90px) 0 30px;
  border-top: 1px solid var(--line);
  background: #070b09;
}

.footer-verse {
  max-width: 790px;
  margin: 0 auto clamp(48px, 7vw, 72px);
  text-align: center;
}

.footer-verse blockquote {
  color: rgba(244, 238, 227, 0.86);
  font-family: var(--font-display);
  font-size: clamp(1.45rem, 2.7vw, 2.1rem);
  font-style: italic;
  font-weight: 300;
  line-height: 1.5;
  letter-spacing: -0.012em;
}

.footer-verse cite {
  display: block;
  margin-top: 20px;
  color: var(--gold);
  font-size: 9px;
  font-style: normal;
  font-weight: 500;
  letter-spacing: 0.26em;
  text-transform: uppercase;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.55fr 0.8fr 0.8fr 1fr;
  gap: 40px;
  padding: clamp(38px, 5vw, 52px) 0;
  border-top: 1px solid var(--line);
}

.footer-brand .brand {
  margin-bottom: 18px;
}

.footer-brand p {
  max-width: 290px;
  color: rgba(244, 238, 227, 0.45);
  font-size: 13px;
  line-height: 1.7;
}

.footer-phone {
  display: inline-block;
  margin-top: 20px;
  color: var(--paper);
  font-family: var(--font-display);
  font-size: 1.42rem;
  line-height: 1.2;
  text-decoration: none;
  transition: color 0.25s ease;
}

.footer-phone:hover {
  color: var(--gold);
}

.footer-col h4 {
  margin-bottom: 18px;
  color: var(--gold);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.footer-col a {
  display: block;
  padding: 6px 0;
  color: rgba(244, 238, 227, 0.6);
  font-size: 13px;
  text-decoration: none;
  transition: color 0.25s ease;
}

.footer-col a:hover {
  color: var(--paper);
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding-top: 26px;
  border-top: 1px solid var(--line);
  color: rgba(244, 238, 227, 0.34);
  font-size: 10.5px;
  letter-spacing: 0.03em;
}

/* ------------------------------------------------------------
   Inner page hero
   ------------------------------------------------------------ */

.page-hero {
  position: relative;
  overflow: hidden;
  padding: clamp(148px, 18vh, 190px) 0 clamp(70px, 8vw, 92px);
  border-bottom: 1px solid var(--line);
  background:
    radial-gradient(ellipse at 82% 12%, rgba(215, 179, 106, 0.1), transparent 50%),
    radial-gradient(ellipse at 8% 85%, rgba(54, 86, 67, 0.16), transparent 52%),
    linear-gradient(160deg, #0a0f0d 0%, #0c1310 60%, #090d0b 100%);
}

.page-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(rgba(244, 238, 227, 0.08) 1px, transparent 1px);
  background-size: 28px 28px;
  opacity: 0.16;
  -webkit-mask-image: radial-gradient(ellipse at 70% 30%, #000, transparent 64%);
  mask-image: radial-gradient(ellipse at 70% 30%, #000, transparent 64%);
}

.page-hero .container {
  position: relative;
  z-index: 1;
}

.breadcrumb {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 34px;
  color: rgba(244, 238, 227, 0.38);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.breadcrumb a {
  color: rgba(244, 238, 227, 0.58);
  text-decoration: none;
  transition: color 0.25s ease;
}

.breadcrumb a:hover {
  color: var(--paper);
}

.breadcrumb span[aria-hidden] {
  color: rgba(215, 179, 106, 0.55);
}

.page-hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(300px, 0.75fr);
  align-items: end;
  gap: clamp(34px, 6vw, 80px);
}

.page-hero h1 {
  max-width: 15ch;
  margin: 8px 0 0;
  font-family: var(--font-display);
  font-size: clamp(2.9rem, 6vw, 5rem);
  font-weight: 350;
  line-height: 1;
  letter-spacing: -0.035em;
}

.page-hero h1 em {
  color: var(--gold);
  font-style: italic;
  font-weight: 340;
}

.page-lead {
  max-width: 590px;
  margin-top: 26px;
  color: rgba(244, 238, 227, 0.62);
  font-size: 15.5px;
  font-weight: 300;
  line-height: 1.8;
}

.hero-scripture {
  margin: 0;
  padding: 6px 0 6px 28px;
  border-left: 1px solid rgba(215, 179, 106, 0.4);
}

.hero-scripture p {
  color: rgba(244, 238, 227, 0.82);
  font-family: var(--font-display);
  font-size: clamp(1.12rem, 1.9vw, 1.32rem);
  font-style: italic;
  line-height: 1.62;
}

.hero-scripture cite {
  display: block;
  margin-top: 16px;
  color: var(--gold);
  font-size: 9px;
  font-style: normal;
  font-weight: 500;
  letter-spacing: 0.24em;
  text-transform: uppercase;
}

.hero-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--line);
}

.hero-stats > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 22px;
  background: #0c1310;
}

.hero-stats strong {
  color: var(--gold);
  font-family: var(--font-display);
  font-size: 2.2rem;
  font-weight: 350;
  line-height: 1;
  letter-spacing: -0.03em;
}

.hero-stats span {
  color: rgba(244, 238, 227, 0.45);
  font-size: 8.5px;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.hero-contact {
  padding: 28px;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: linear-gradient(150deg, rgba(255, 255, 255, 0.055), rgba(255, 255, 255, 0.015));
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.hero-contact-label {
  color: var(--gold);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.hero-contact-number {
  display: block;
  margin: 10px 0 12px;
  color: var(--paper);
  font-family: var(--font-display);
  font-size: clamp(1.9rem, 3vw, 2.3rem);
  font-weight: 400;
  line-height: 1.1;
  text-decoration: none;
  transition: color 0.25s ease;
}

.hero-contact-number:hover {
  color: var(--gold);
}

.hero-contact p {
  color: rgba(244, 238, 227, 0.52);
  font-size: 12.5px;
  line-height: 1.65;
}

.hero-contact-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 20px;
}

/* ------------------------------------------------------------
   About article
   ------------------------------------------------------------ */

.article-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  align-items: start;
  gap: clamp(40px, 6vw, 84px);
}

.article {
  max-width: 700px;
}

.article-callout {
  margin-bottom: 34px;
  padding-bottom: 26px;
  border-bottom: 1px solid var(--line-dark);
  color: var(--ink-text);
  font-family: var(--font-display);
  font-size: clamp(1.28rem, 2.4vw, 1.65rem);
  line-height: 1.5;
  letter-spacing: -0.01em;
}

.article-callout em {
  color: var(--gold-2);
  font-style: italic;
}

.article p {
  margin-bottom: 22px;
  color: #475047;
  font-size: 16.5px;
  line-height: 1.88;
}

.article p.dropcap::first-letter {
  float: left;
  padding: 9px 12px 0 0;
  color: var(--gold-2);
  font-family: var(--font-display);
  font-size: 4.5rem;
  font-weight: 400;
  line-height: 0.72;
}

.article h2 {
  margin: 54px 0 18px;
  color: var(--ink-text);
  font-family: var(--font-display);
  font-size: clamp(1.7rem, 3vw, 2.3rem);
  font-weight: 400;
  line-height: 1.14;
  letter-spacing: -0.022em;
}

.article blockquote {
  margin: 36px 0;
  padding: 6px 0 6px 28px;
  border-left: 2px solid var(--gold-2);
  color: #2d362e;
  font-family: var(--font-display);
  font-size: clamp(1.2rem, 2.2vw, 1.4rem);
  font-style: italic;
  line-height: 1.6;
}

.article blockquote cite {
  display: block;
  margin-top: 14px;
  color: var(--gold-2);
  font-family: var(--font-body);
  font-size: 9px;
  font-style: normal;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.article-end {
  margin-top: 56px;
  padding: clamp(28px, 4vw, 36px);
  border: 1px solid var(--line-dark);
  border-radius: 18px;
  background: #ece4d5;
}

.article-end .kicker {
  margin-bottom: 16px;
}

.article-end h3 {
  margin-bottom: 12px;
  color: var(--ink-text);
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 2.6vw, 1.85rem);
  font-weight: 400;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.article-end > p:not(.kicker) {
  margin-bottom: 22px;
  color: var(--muted-2);
  font-size: 14px;
  line-height: 1.72;
}

.article-end-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

/* About sidebar */

.sidebar {
  position: sticky;
  top: 118px;
  display: grid;
  gap: 16px;
}

.sidebar-card {
  padding: 24px;
  border: 1px solid var(--line-dark);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.38);
}

.sidebar-card h3 {
  margin-bottom: 14px;
  color: var(--gold-2);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.toc a {
  display: block;
  padding: 9px 0;
  border-bottom: 1px solid var(--line-dark);
  color: #3f473f;
  font-size: 12.5px;
  line-height: 1.5;
  text-decoration: none;
  transition: color 0.25s ease;
}

.toc a:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.toc a:hover {
  color: var(--ink-text);
}

.sidebar-quote {
  position: relative;
  overflow: hidden;
  background: var(--ink);
  border-color: rgba(215, 179, 106, 0.2);
}

.sidebar-quote::after {
  content: "";
  position: absolute;
  right: -60px;
  bottom: -90px;
  width: 180px;
  height: 180px;
  border: 1px solid rgba(215, 179, 106, 0.16);
  border-radius: 50%;
}

.sidebar-mark {
  display: block;
  margin-bottom: 14px;
  color: var(--gold);
  font-size: 16px;
}

.sidebar-quote p {
  position: relative;
  z-index: 1;
  color: rgba(244, 238, 227, 0.76);
  font-family: var(--font-display);
  font-size: 1.02rem;
  font-style: italic;
  line-height: 1.6;
}

.sidebar-card > p {
  color: var(--muted-2);
  font-size: 12.8px;
  line-height: 1.7;
}

.sidebar-phone {
  display: block;
  margin-top: 10px;
  color: var(--ink-text);
  font-family: var(--font-display);
  font-size: 1.42rem;
  line-height: 1.2;
  text-decoration: none;
}

.sidebar-phone:hover {
  color: var(--gold-2);
}

.sidebar-wa {
  display: inline-block;
  margin-top: 10px;
  color: var(--gold-2);
  font-size: 11.5px;
  font-weight: 500;
  text-decoration: none;
}

.sidebar-wa:hover {
  color: var(--ink-text);
}

.sidebar-ad {
  position: relative;
  overflow: hidden;
  padding: 24px;
  border: 1px solid rgba(215, 179, 106, 0.22);
  border-radius: 16px;
  background: linear-gradient(145deg, #0c120f, #101a15);
  color: var(--paper);
}

.sidebar-ad .ad-label {
  margin-bottom: 20px;
}

.sidebar-ad .dlife-mark {
  margin-bottom: 4px;
  font-size: 1.5rem;
}

.sidebar-ad-name {
  margin-bottom: 12px;
  color: var(--gold);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.sidebar-ad p {
  color: rgba(244, 238, 227, 0.52);
  font-size: 12px;
  line-height: 1.65;
}

.sidebar-ad > a {
  display: inline-block;
  margin-top: 16px;
  color: var(--gold);
  font-size: 11.5px;
  font-weight: 500;
  text-decoration: none;
}

.sidebar-ad > a:hover {
  color: var(--gold-soft);
}

/* ------------------------------------------------------------
   Library page
   ------------------------------------------------------------ */

.library-page {
  padding-top: clamp(58px, 7vw, 84px);
}

.library-intro {
  margin-bottom: 36px;
}

.library-intro-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 44px;
}

.library-intro-row .section-title {
  max-width: 17ch;
}

.library-intro-row > p {
  max-width: 380px;
  margin-bottom: 4px;
  color: var(--muted-2);
  font-size: 14px;
  line-height: 1.75;
}

.library-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px;
  border: 1px solid var(--line-dark);
  border-radius: 18px;
  background: #ece4d5;
}

.search-field {
  position: relative;
  flex: 1 1 260px;
  max-width: 380px;
}

.search-field svg {
  position: absolute;
  top: 50%;
  left: 16px;
  width: 18px;
  height: 18px;
  color: var(--muted-2);
  transform: translateY(-50%);
  pointer-events: none;
}

.search-field input {
  width: 100%;
  padding: 13px 16px 13px 44px;
  border: 1px solid transparent;
  border-radius: 999px;
  outline: none;
  background: var(--paper);
  color: var(--ink-text);
  font-size: 13.5px;
  transition: border-color 0.25s ease, box-shadow 0.25s ease;
}

.search-field input::placeholder {
  color: #8a9087;
}

.search-field input:focus {
  border-color: var(--gold-2);
  box-shadow: 0 0 0 3px rgba(185, 143, 67, 0.14);
}

.filter-group {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.filter-btn {
  padding: 11px 16px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: transparent;
  color: #4f574f;
  font-size: 11.5px;
  font-weight: 500;
  letter-spacing: 0.03em;
  line-height: 1;
  transition: background 0.25s ease, color 0.25s ease;
}

.filter-btn:hover {
  background: rgba(23, 32, 26, 0.06);
}

.filter-btn.is-active {
  background: var(--ink);
  color: var(--paper);
}

.library-results {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin: 22px 2px 0;
  color: var(--muted-2);
  font-size: 9.5px;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.library-results p {
  color: var(--ink-text);
  font-weight: 600;
}

.lib-group {
  padding-top: clamp(46px, 6vw, 60px);
}

.lib-group-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;
  margin-bottom: 24px;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--line-dark);
}

.lib-group-kicker {
  display: block;
  margin-bottom: 10px;
  color: var(--gold-2);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.lib-group-head h2 {
  color: var(--ink-text);
  font-family: var(--font-display);
  font-size: clamp(1.7rem, 3vw, 2.1rem);
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.lib-group-head p {
  max-width: 470px;
  margin-top: 9px;
  color: var(--muted-2);
  font-size: 13px;
  line-height: 1.65;
}

.lib-count-badge {
  flex: none;
  padding: 8px 12px;
  border: 1px solid var(--line-dark);
  border-radius: 999px;
  color: var(--muted-2);
  font-size: 8.5px;
  font-weight: 500;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.lib-items {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.lib-card {
  position: relative;
  display: flex;
  min-height: 126px;
  flex-direction: column;
  gap: 10px;
  overflow: hidden;
  padding: 21px 40px 19px 22px;
  border: 1px solid var(--line-dark);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.34);
  color: var(--ink-text);
  text-decoration: none;
  transition: background 0.3s ease, border-color 0.3s ease, transform 0.3s var(--ease);
}

.lib-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 2px;
  background: var(--gold-2);
  transform: scaleY(0);
  transform-origin: top;
  transition: transform 0.3s var(--ease);
}

.lib-card:hover {
  border-color: rgba(185, 143, 67, 0.38);
  background: #fffaf1;
  transform: translateY(-2px);
}

.lib-card:hover::before {
  transform: scaleY(1);
}

.lib-card::after {
  content: "";
  position: absolute;
  top: 20px;
  right: 21px;
  width: 7px;
  height: 7px;
  border-top: 1.2px solid var(--gold-2);
  border-right: 1.2px solid var(--gold-2);
  transform: rotate(45deg);
  opacity: 0.45;
  transition: opacity 0.3s ease, transform 0.3s var(--ease);
}

.lib-card:hover::after {
  opacity: 1;
  transform: translate(2px, -2px) rotate(45deg);
}

.lib-num {
  color: #8f958c;
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.18em;
}

.lib-card h3 {
  flex: 1;
  color: var(--ink-text);
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 450;
  line-height: 1.32;
  letter-spacing: -0.01em;
}

.lib-type {
  color: var(--gold-2);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.is-hidden {
  display: none !important;
}

.empty-state {
  margin-top: 48px;
  padding: 64px 24px;
  border: 1px dashed rgba(23, 32, 26, 0.22);
  border-radius: 18px;
  text-align: center;
}

.empty-state > span {
  display: block;
  margin-bottom: 14px;
  color: var(--gold-2);
  font-size: 18px;
}

.empty-state h3 {
  color: var(--ink-text);
  font-family: var(--font-display);
  font-size: 1.7rem;
  font-weight: 400;
}

.empty-state p {
  margin-top: 8px;
  color: var(--muted-2);
  font-size: 13.5px;
}

.library-end {
  position: relative;
  overflow: hidden;
  margin-top: clamp(60px, 8vw, 84px);
  padding: clamp(36px, 5vw, 58px);
  border-radius: 22px;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(215, 179, 106, 0.14), transparent 60%),
    var(--ink);
  color: var(--paper);
  text-align: center;
}

.library-end::after {
  content: "";
  position: absolute;
  top: -80px;
  right: -70px;
  width: 220px;
  height: 220px;
  border: 1px solid rgba(215, 179, 106, 0.16);
  border-radius: 50%;
}

.library-end .kicker {
  position: relative;
  z-index: 1;
  margin-bottom: 18px;
  color: var(--gold);
}

.library-end blockquote {
  position: relative;
  z-index: 1;
  max-width: 740px;
  margin: 0 auto;
  color: rgba(244, 238, 227, 0.88);
  font-family: var(--font-display);
  font-size: clamp(1.4rem, 2.8vw, 2rem);
  font-style: italic;
  font-weight: 300;
  line-height: 1.5;
}

.library-end cite {
  position: relative;
  z-index: 1;
  display: block;
  margin-top: 14px;
  color: var(--gold);
  font-size: 8.5px;
  font-style: normal;
  font-weight: 500;
  letter-spacing: 0.24em;
  text-transform: uppercase;
}

.library-end > p:last-child {
  position: relative;
  z-index: 1;
  max-width: 510px;
  margin: 24px auto 0;
  color: rgba(244, 238, 227, 0.48);
  font-size: 13px;
  line-height: 1.72;
}

/* ------------------------------------------------------------
   Contact page
   ------------------------------------------------------------ */

.contact-layout {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  align-items: start;
  gap: clamp(40px, 7vw, 88px);
}

.contact-copy {
  max-width: 49ch;
  margin: 22px 0 30px;
  color: var(--muted-2);
  font-size: 15px;
  line-height: 1.8;
}

.contact-cards {
  display: grid;
  gap: 12px;
}

.contact-card {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 19px 22px;
  border: 1px solid var(--line-dark);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.4);
  color: var(--ink-text);
  text-decoration: none;
  transition: transform 0.3s var(--ease), background 0.3s ease, border-color 0.3s ease;
}

.contact-card:hover {
  border-color: rgba(185, 143, 67, 0.4);
  background: #fffaf1;
  transform: translateY(-2px);
}

.contact-card-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  flex: none;
  border-radius: 50%;
  background: rgba(185, 143, 67, 0.12);
  color: var(--gold-2);
}

.contact-card-icon svg {
  width: 21px;
  height: 21px;
}

.contact-card-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 2px;
}

.contact-card-label {
  color: var(--muted-2);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.contact-card-body strong {
  color: var(--ink-text);
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 450;
  line-height: 1.2;
}

.contact-card-hint {
  color: #8a9087;
  font-size: 10.5px;
}

.contact-card-arrow {
  color: var(--gold-2);
  font-size: 18px;
  transition: transform 0.3s var(--ease);
}

.contact-card:hover .contact-card-arrow {
  transform: translateX(4px);
}

.contact-partner {
  margin-top: 28px;
  padding: 26px;
  border: 1px solid var(--line-dark);
  border-radius: 18px;
  background: #ece4d5;
}

.contact-partner-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
}

.contact-partner .ad-label {
  border-color: rgba(23, 32, 26, 0.16);
  color: var(--muted-2);
}

.contact-partner .dlife-mark {
  color: var(--ink-text);
  font-size: 1.35rem;
}

.contact-partner h3 {
  margin-bottom: 8px;
  color: var(--ink-text);
  font-family: var(--font-display);
  font-size: 1.45rem;
  font-weight: 400;
  line-height: 1.2;
}

.contact-partner p {
  color: var(--muted-2);
  font-size: 12.8px;
  line-height: 1.7;
}

.contact-partner > a {
  display: inline-block;
  margin-top: 14px;
  color: var(--gold-2);
  font-size: 11.5px;
  font-weight: 600;
  text-decoration: none;
}

.contact-partner > a:hover {
  color: var(--ink-text);
}

.contact-form-wrap {
  padding: clamp(28px, 4vw, 44px);
  border: 1px solid rgba(215, 179, 106, 0.18);
  border-radius: 22px;
  background:
    radial-gradient(ellipse at 90% 0%, rgba(215, 179, 106, 0.1), transparent 50%),
    linear-gradient(150deg, #0c1310, #0f1813);
  color: var(--paper);
  box-shadow: 0 40px 70px -56px rgba(10, 15, 13, 0.65);
}

.form-eyebrow {
  display: inline-block;
  margin-bottom: 12px;
  color: var(--gold);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.contact-form-wrap h3 {
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 3vw, 2.2rem);
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.form-intro {
  max-width: 42ch;
  margin: 12px 0 28px;
  color: rgba(244, 238, 227, 0.5);
  font-size: 12.8px;
  line-height: 1.7;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-bottom: 18px;
}

.field label {
  color: rgba(244, 238, 227, 0.55);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.field input,
.field select,
.field textarea {
  width: 100%;
  padding: 14px 16px;
  border: 1px solid rgba(244, 238, 227, 0.14);
  border-radius: 10px;
  outline: none;
  background: rgba(255, 255, 255, 0.035);
  color: var(--paper);
  font-size: 14px;
  line-height: 1.5;
  transition: border-color 0.25s ease, box-shadow 0.25s ease, background 0.25s ease;
}

.field textarea {
  min-height: 140px;
  resize: vertical;
}

.field input::placeholder,
.field textarea::placeholder {
  color: rgba(244, 238, 227, 0.28);
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  border-color: var(--gold-2);
  background: rgba(255, 255, 255, 0.05);
  box-shadow: 0 0 0 3px rgba(215, 179, 106, 0.1);
}

.field input.is-invalid,
.field textarea.is-invalid {
  border-color: #c9826d;
  box-shadow: 0 0 0 3px rgba(201, 130, 109, 0.1);
}

.field select option {
  color: #17201a;
  background: #f4eee3;
}

.form-submit {
  width: 100%;
  margin-top: 4px;
}

.form-submit:disabled {
  opacity: 0.6;
  cursor: wait;
  transform: none;
}

.form-note {
  margin-top: 14px;
  color: rgba(244, 238, 227, 0.36);
  font-size: 10.5px;
  line-height: 1.6;
}

.form-status {
  min-height: 20px;
  margin-top: 10px;
  color: var(--gold);
  font-size: 12px;
  line-height: 1.6;
}

.form-status.is-error {
  color: #e2a08a;
}

/* ------------------------------------------------------------
   Responsive
   ------------------------------------------------------------ */

@media (max-width: 1120px) {
  .library-grid {
    gap: 14px;
  }

  .footer-grid {
    grid-template-columns: 1.4fr 0.8fr 0.8fr 1fr;
    gap: 30px;
  }
}

@media (max-width: 1020px) {
  .hero-grid {
    grid-template-columns: 1fr;
    gap: 30px;
  }

  .hero h1 {
    max-width: 12ch;
  }

  .hero-art {
    max-width: 430px;
    margin: 10px auto 0;
  }

  .hero-glow {
    top: 35%;
    right: -160px;
    opacity: 0.8;
  }

  .hero-lead {
    max-width: 620px;
  }

  .section-head {
    align-items: flex-start;
    flex-direction: column;
    gap: 22px;
  }

  .section-head > p {
    max-width: 560px;
  }

  .article-layout {
    grid-template-columns: 1fr;
  }

  .article {
    max-width: 740px;
  }

  .sidebar {
    position: static;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .sidebar-ad {
    grid-column: 1 / -1;
  }

  .contact-layout {
    grid-template-columns: 1fr;
    gap: 44px;
  }

  .contact-info {
    max-width: 720px;
  }

  .lib-items {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .footer-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 34px;
  }
}

@media (max-width: 900px) {
  .site-header {
    background: rgba(8, 13, 10, 0.72);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
  }

  .site-header.is-scrolled {
    background: rgba(8, 13, 10, 0.94);
  }

  .header-inner {
    height: 76px;
  }

  .site-nav {
    position: absolute;
    top: calc(100% + 8px);
    right: 20px;
    left: 20px;
    z-index: 210;
    flex-direction: column;
    align-items: stretch;
    gap: 3px;
    padding: 14px;
    border: 1px solid var(--line);
    border-radius: 18px;
    background: #0a100c;
    box-shadow: 0 30px 60px -24px rgba(0, 0, 0, 0.6);
    opacity: 0;
    visibility: hidden;
    transform: translateY(-10px);
    transition: opacity 0.28s ease, transform 0.28s var(--ease), visibility 0.28s;
  }

  .site-nav.is-open {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
  }

  .nav-link {
    padding: 13px 12px;
    border-radius: 10px;
    font-size: 14.5px;
  }

  .nav-link::after {
    display: none;
  }

  .nav-link:hover,
  .nav-link[aria-current="page"] {
    background: rgba(215, 179, 106, 0.07);
  }

  .nav-cta {
    justify-content: center;
    margin: 8px 0 0;
  }

  .nav-toggle {
    display: flex;
  }

  .page-hero-grid {
    grid-template-columns: 1fr;
    align-items: start;
    gap: 34px;
  }

  .hero-scripture {
    max-width: 560px;
  }

  .hero-stats {
    max-width: 440px;
  }

  .hero-contact {
    max-width: 440px;
  }

  .split {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .split-side {
    position: static;
  }

  .split-side .section-title {
    max-width: 18ch;
  }

  .prose {
    justify-self: start;
    max-width: 680px;
  }

  .library-intro-row {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
  }

  .partner-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }
}

@media (max-width: 760px) {
  .container {
    width: calc(100% - 44px);
  }

  .hero {
    padding-top: 132px;
  }

  .hero h1 {
    font-size: clamp(2.9rem, 12vw, 4.1rem);
  }

  .library-grid {
    grid-template-columns: 1fr;
  }

  .pillars {
    gap: 12px;
  }

  .partner-head {
    align-items: flex-start;
    flex-direction: column;
    gap: 16px;
    margin-bottom: 30px;
  }

  .dlife-brand {
    align-items: flex-start;
  }

  .partner-grid h2 {
    font-size: clamp(2.1rem, 8vw, 3rem);
  }

  .footer-bottom {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }

  .article p,
  .prose p {
    font-size: 15.5px;
  }

  .article h2 {
    margin-top: 44px;
  }

  .sidebar {
    grid-template-columns: 1fr;
  }

  .sidebar-ad {
    grid-column: auto;
  }

  .library-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .search-field {
    flex: 0 0 auto;
    max-width: none;
  }

  .library-results {
    align-items: flex-start;
    flex-direction: column;
    gap: 5px;
  }

  .lib-group-head {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
  }

  .hero-stats {
    width: 100%;
    max-width: none;
  }

  .contact-partner-head {
    align-items: flex-start;
    flex-direction: column;
  }

  .verse-inner {
    flex-direction: column;
    gap: 8px;
  }

  .verse-ref {
    order: 3;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-brand {
    grid-column: 1 / -1;
  }

  .partner-card {
    border-radius: 22px;
  }
}

@media (max-width: 560px) {
  .container {
    width: calc(100% - 36px);
  }

  .header-inner {
    height: 72px;
  }

  .site-nav {
    top: calc(100% + 6px);
    right: 12px;
    left: 12px;
  }

  .brand-mark {
    width: 34px;
    height: 34px;
  }

  .brand-name {
    font-size: 1.02rem;
  }

  .brand-sub {
    font-size: 7.5px;
    letter-spacing: 0.24em;
  }

  .hero {
    padding-top: 118px;
    padding-bottom: 66px;
  }

  .hero h1 {
    margin-top: 18px;
    font-size: clamp(2.65rem, 14.5vw, 3.55rem);
  }

  .hero-lead {
    font-size: 0.98rem;
  }

  .hero-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .hero-meta {
    margin-top: 30px;
    font-size: 9.5px;
  }

  .hero-meta li + li::before {
    margin: 0 8px;
  }

  .hero-art {
    max-width: 320px;
  }

  .hourglass {
    width: 100%;
  }

  .art-caption {
    gap: 10px;
    font-size: 7.5px;
    letter-spacing: 0.22em;
  }

  .art-caption span {
    width: 20px;
  }

  .verse-strip {
    padding: 22px 0;
  }

  .verse-text {
    font-size: 0.95rem;
  }

  .section {
    padding: 68px 0;
  }

  .section-title {
    font-size: clamp(1.85rem, 8vw, 2.4rem);
  }

  .pillars {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .pillars li {
    padding: 15px 0;
    border-bottom: 1px solid var(--line-dark);
  }

  .pillars li:last-child {
    border-bottom: 0;
  }

  .pillars span {
    margin-bottom: 6px;
  }

  .library-card {
    padding: 25px 22px;
  }

  .partner-card {
    padding: 28px 22px;
    border-radius: 20px;
  }

  .partner-head {
    margin-bottom: 26px;
  }

  .partner-tags {
    margin: 20px 0 26px;
  }

  .partner-copy .btn {
    width: 100%;
  }

  .cta-band {
    padding: 68px 0;
  }

  .cta-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .cta-actions .btn {
    width: 100%;
  }

  .page-hero {
    padding: 122px 0 64px;
  }

  .page-hero h1 {
    font-size: clamp(2.5rem, 12vw, 3.4rem);
  }

  .page-lead {
    font-size: 14.5px;
  }

  .hero-scripture {
    padding-left: 20px;
  }

  .hero-contact {
    padding: 23px;
  }

  .article-end-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .article-end-actions .btn {
    width: 100%;
  }

  .lib-items {
    grid-template-columns: 1fr;
  }

  .lib-card {
    min-height: 112px;
  }

  .library-intro-row .section-title {
    max-width: 100%;
  }

  .filter-group {
    gap: 4px;
  }

  .filter-btn {
    padding: 10px 13px;
    font-size: 11px;
  }

  .contact-card {
    gap: 14px;
    padding: 17px;
  }

  .contact-card-icon {
    width: 44px;
    height: 44px;
  }

  .contact-form-wrap {
    padding: 26px 21px;
    border-radius: 18px;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-brand {
    grid-column: auto;
  }

  .footer-verse blockquote {
    font-size: 1.38rem;
  }

  .library-end {
    border-radius: 18px;
    text-align: left;
  }

  .library-end .kicker {
    justify-content: flex-start;
  }

  .library-end blockquote {
    margin: 0;
  }

  .library-end > p:last-child {
    margin-left: 0;
  }
}

/* ------------------------------------------------------------
   Motion preferences
   ------------------------------------------------------------ */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .js .reveal {
    opacity: 1;
    transform: none;
  }
}


/* ------------------------------------------------------------
   Blogger integration
   ------------------------------------------------------------ */

@media (min-width: 901px) {
  .site-nav {
    gap: 21px;
  }
}

/* Hide Blogger's own navbar / quick-edit chrome if it is injected */
#navbar-iframe,
#navbar,
.navbar {
  display: none !important;
  height: 0 !important;
  visibility: hidden !important;
}

/* Page bodies rendered from Blogger Pages */
.page-content {
  min-height: 50vh;
}

.page-content.is-plain {
  padding: clamp(150px, 18vh, 190px) 0 clamp(72px, 9vw, 100px);
}

.page-content.is-plain > * {
  width: min(760px, calc(100% - 56px));
  margin-inline: auto;
}

.page-content.is-plain > * + * {
  margin-top: 20px;
}

.page-content.is-plain h1,
.page-content.is-plain h2,
.page-content.is-plain h3 {
  color: var(--paper);
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1.15;
}

.page-content.is-plain h1 {
  font-size: clamp(2.5rem, 5vw, 4rem);
}

.page-content.is-plain h2 {
  margin-top: 38px;
  font-size: clamp(1.6rem, 3vw, 2.2rem);
}

.page-content.is-plain p,
.page-content.is-plain li {
  color: rgba(244, 238, 227, 0.68);
  font-size: 16px;
  line-height: 1.8;
}

.page-content.is-plain a {
  color: var(--gold);
}

.page-content.is-plain ul,
.page-content.is-plain ol {
  padding-left: 22px;
}

/* Blog index / latest posts */
.blog-home {
  border-top: 1px solid var(--line-dark);
  padding-top: clamp(72px, 9vw, 108px);
}

.blog-home .section-head {
  margin-bottom: 42px;
}

.blog-home .section-head > p {
  color: var(--muted-2);
}

.post-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}

.blog-home .post-grid .post-card:nth-child(n + 7) {
  display: none;
}

.post-card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--line-dark);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.38);
  color: var(--ink-text);
  text-decoration: none;
  transition: transform 0.3s var(--ease), border-color 0.3s ease, background 0.3s ease;
}

.post-card:hover {
  border-color: rgba(185, 143, 67, 0.38);
  background: #fffaf1;
  transform: translateY(-3px);
}

.post-card-media {
  overflow: hidden;
  aspect-ratio: 16 / 9;
  background: #e3d8c5;
}

.post-card-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.6s var(--ease);
}

.post-card-media--empty {
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle at 82% 18%, rgba(215, 179, 106, 0.16), transparent 55%),
    linear-gradient(150deg, #0e1612, #0a0f0d);
}

.post-card-media--empty svg {
  width: 42px;
  height: 42px;
  color: rgba(215, 179, 106, 0.8);
}

.post-card:hover .post-card-media img {
  transform: scale(1.04);
}

.post-card-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 10px;
  padding: 22px;
}

.post-card-meta {
  color: var(--gold-2);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.post-card h2 {
  margin: 0;
  color: var(--ink-text);
  font-family: var(--font-display);
  font-size: 1.33rem;
  font-weight: 450;
  line-height: 1.25;
  letter-spacing: -0.012em;
}

.post-card p {
  flex: 1;
  color: var(--muted-2);
  font-size: 13.5px;
  line-height: 1.7;
}

.post-card-link {
  margin-top: 6px;
  padding-top: 14px;
  border-top: 1px solid var(--line-dark);
  color: var(--gold-2);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.post-card-link span {
  display: inline-block;
  margin-left: 6px;
  transition: transform 0.3s var(--ease);
}

.post-card:hover .post-card-link span {
  transform: translateX(3px);
}

.blog-more {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 14px 30px;
  margin-top: 36px;
  text-align: center;
}

.blog-empty {
  padding: 54px 26px;
  border: 1px dashed rgba(23, 32, 26, 0.22);
  border-radius: 18px;
  text-align: center;
}

.blog-empty > span {
  display: block;
  margin-bottom: 14px;
  color: var(--gold-2);
  font-size: 18px;
}

.blog-empty h3 {
  color: var(--ink-text);
  font-family: var(--font-display);
  font-size: 1.7rem;
  font-weight: 400;
}

.blog-empty p {
  max-width: 46ch;
  margin: 8px auto 22px;
  color: var(--muted-2);
  font-size: 13.5px;
  line-height: 1.7;
}

.blog-pager {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 12px;
  margin-top: 42px;
}

/* Blog archive hero and search */
.blog-archive-hero .page-hero-grid {
  align-items: center;
}

.blog-search {
  display: flex;
  gap: 8px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.035);
}

.blog-search input {
  min-width: 0;
  flex: 1;
  padding: 10px 12px;
  border: 1px solid transparent;
  border-radius: 999px;
  outline: none;
  background: rgba(255, 255, 255, 0.06);
  color: var(--paper);
  font-size: 13px;
}

.blog-search input::placeholder {
  color: rgba(244, 238, 227, 0.34);
}

.blog-search input:focus {
  border-color: rgba(215, 179, 106, 0.55);
}

.blog-search .btn {
  min-height: 42px;
  padding: 0 18px;
}

/* Single post */
.post-hero h1 {
  max-width: 20ch;
}

.post-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin-top: 22px;
  color: rgba(244, 238, 227, 0.62);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.post-meta .dot {
  color: var(--gold);
}

.post-layout {
  max-width: 820px;
  margin: 0 auto;
}

.post-body {
  color: #475047;
}

.post-body > * + * {
  margin-top: 22px;
}

.post-body p {
  color: #475047;
  font-size: 16.5px;
  line-height: 1.88;
}

.post-body .post-intro {
  color: #2c352d;
  font-family: var(--font-display);
  font-size: clamp(1.18rem, 2vw, 1.42rem);
  font-weight: 400;
  line-height: 1.65;
  letter-spacing: -0.01em;
}

.post-body h2 {
  margin-top: 48px;
  color: var(--ink-text);
  font-family: var(--font-display);
  font-size: clamp(1.7rem, 3vw, 2.25rem);
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.022em;
}

.post-body h3 {
  margin-top: 34px;
  color: var(--ink-text);
  font-family: var(--font-display);
  font-size: clamp(1.3rem, 2.2vw, 1.6rem);
  font-weight: 450;
  line-height: 1.25;
  letter-spacing: -0.015em;
}

.post-body a {
  color: var(--gold-2);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.post-body a:hover {
  color: var(--ink-text);
}

.post-body a.btn,
.post-body a.btn:hover {
  text-decoration: none;
}

.post-body a.btn-dark,
.post-body a.btn-ghost {
  color: var(--paper);
}

.post-body a.btn-outline-dark {
  color: var(--ink-text);
}

.post-body a.btn-gold {
  color: #181206;
}

.post-body strong {
  color: var(--ink-text);
  font-weight: 600;
}

.post-body ul,
.post-body ol {
  padding-left: 24px;
}

.post-body li {
  margin-bottom: 8px;
  color: #475047;
  font-size: 16px;
  line-height: 1.8;
}

.post-body blockquote {
  margin: 36px 0;
  padding: 6px 0 6px 28px;
  border-left: 2px solid var(--gold-2);
  color: #2d362e;
  font-family: var(--font-display);
  font-size: clamp(1.2rem, 2.2vw, 1.4rem);
  font-style: italic;
  line-height: 1.6;
}

.post-body blockquote cite {
  display: block;
  margin-top: 14px;
  color: var(--gold-2);
  font-family: var(--font-body);
  font-size: 9px;
  font-style: normal;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.post-body img {
  width: auto;
  max-width: 100%;
  height: auto;
  border-radius: 14px;
}

.post-body .separator {
  margin: 30px 0;
}

.post-body .separator img {
  height: auto;
}

.post-body figure {
  margin: 30px 0;
}

.post-body figcaption {
  margin-top: 10px;
  color: var(--muted-2);
  font-size: 11px;
  letter-spacing: 0.04em;
  text-align: center;
}

.post-body hr {
  margin: 40px 0;
  border: 0;
  border-top: 1px solid var(--line-dark);
}

.post-body iframe {
  max-width: 100%;
  border-radius: 14px;
}

.post-body iframe[src*="youtube"],
.post-body iframe[src*="vimeo"] {
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 9;
}

.post-body table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

.post-body th,
.post-body td {
  padding: 10px 12px;
  border: 1px solid var(--line-dark);
  text-align: left;
}

.post-body th {
  color: var(--ink-text);
  background: #ece4d5;
}

.post-body code {
  padding: 2px 5px;
  border-radius: 4px;
  background: #ece4d5;
  color: #2d362e;
  font-size: 0.9em;
}

.post-body pre {
  overflow: auto;
  padding: 18px;
  border-radius: 12px;
  background: #0c1310;
  color: #e8dfcf;
}

.post-body pre code {
  padding: 0;
  background: none;
  color: inherit;
}

.post-body .post-cta {
  margin: 46px 0 8px;
  padding: clamp(26px, 4vw, 34px);
  border: 1px solid var(--line-dark);
  border-radius: 18px;
  background: #ece4d5;
}

.post-body .post-cta h3 {
  margin: 0 0 10px;
  font-size: clamp(1.4rem, 2.4vw, 1.75rem);
}

.post-body .post-cta p {
  color: var(--muted-2);
  font-size: 14px;
  line-height: 1.72;
}

.post-body .post-cta .btn {
  margin-top: 6px;
}

.post-footer {
  margin-top: 56px;
  padding-top: 26px;
  border-top: 1px solid var(--line-dark);
}

.post-labels {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-bottom: 22px;
}

.post-labels span {
  color: var(--muted-2);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.post-labels a {
  padding: 7px 11px;
  border: 1px solid var(--line-dark);
  border-radius: 999px;
  color: var(--gold-2);
  font-size: 9.5px;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-decoration: none;
}

.post-labels a:hover {
  border-color: var(--gold-2);
}

.post-footer-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

@media (max-width: 1020px) {
  .post-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .post-grid {
    grid-template-columns: 1fr;
  }

  .blog-search {
    flex-direction: column;
  }

  .blog-search .btn {
    width: 100%;
  }

  .post-body p,
  .post-body li {
    font-size: 15.5px;
  }

  .post-footer-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .post-footer-actions .btn {
    width: 100%;
  }
}

@media (max-width: 560px) {
  .page-content.is-plain > * {
    width: calc(100% - 36px);
  }

  .post-card-body {
    padding: 20px;
  }

  .post-hero h1 {
    max-width: 100%;
  }
}

body.script:
//
(() => {
  "use strict";

  window.__bankOfTimeReady = true;

  const header = document.getElementById("siteHeader");
  const navToggle = document.getElementById("navToggle");
  const nav = document.getElementById("siteNav");

  /* Header background on scroll */
  if (header) {
    const updateHeader = () => {
      header.classList.toggle("is-scrolled", window.scrollY > 12);
    };
    updateHeader();
    window.addEventListener("scroll", updateHeader, { passive: true });
  }

  /* Mobile navigation */
  if (navToggle && nav) {
    const setNavState = (open) => {
      nav.classList.toggle("is-open", open);
      navToggle.setAttribute("aria-expanded", String(open));
      navToggle.setAttribute("aria-label", open ? "Close menu" : "Open menu");
    };

    navToggle.addEventListener("click", () => {
      setNavState(!nav.classList.contains("is-open"));
    });

    nav.querySelectorAll("a").forEach((link) => {
      link.addEventListener("click", () => setNavState(false));
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && nav.classList.contains("is-open")) {
        setNavState(false);
        navToggle.focus();
      }
    });

    document.addEventListener("click", (event) => {
      if (
        nav.classList.contains("is-open") &&
        !nav.contains(event.target) &&
        !navToggle.contains(event.target)
      ) {
        setNavState(false);
      }
    });

    window.addEventListener("resize", () => {
      if (window.innerWidth > 900) setNavState(false);
    });
  }

  /* Mark the current section in the navigation */
  const currentPath =
    window.location.pathname.replace(/\/+$/, "") || "/";

  const navLinks = [...document.querySelectorAll(".site-nav .nav-link")];

  const markActiveNav = () => {
    navLinks.forEach((link) => {
      let url;
      try {
        url = new URL(link.href, window.location.origin);
      } catch (error) {
        return;
      }

      const linkPath = url.pathname.replace(/\/+$/, "") || "/";
      const linkHash = url.hash;
      let active = false;

      if (linkHash) {
        active = currentPath === linkPath && window.location.hash === linkHash;
      } else if (linkPath === "/") {
        active = currentPath === "/" || currentPath === "/index.html";
      } else if (linkPath === "/search") {
        active =
          currentPath === "/search" ||
          currentPath.startsWith("/search/") ||
          /^\/\d{4}\//.test(currentPath);
      } else {
        active =
          currentPath === linkPath ||
          currentPath === linkPath.replace(/\.html$/, "") ||
          currentPath.startsWith(linkPath + "/");
      }

      if (active) link.setAttribute("aria-current", "page");
      else link.removeAttribute("aria-current");
    });
  };

  markActiveNav();
  window.addEventListener("hashchange", markActiveNav);

  /* Reveal on scroll */
  const revealItems = document.querySelectorAll(".reveal");
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  if (revealItems.length) {
    if ("IntersectionObserver" in window && !reduceMotion) {
      const observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              entry.target.classList.add("is-visible");
              observer.unobserve(entry.target);
            }
          });
        },
        { threshold: 0.12, rootMargin: "0px 0px -40px 0px" }
      );

      revealItems.forEach((item) => observer.observe(item));
    } else {
      revealItems.forEach((item) => item.classList.add("is-visible"));
    }
  }

  /* Plain Blogger pages without their own section layout */
  const pageContent = document.querySelector(".page-content");
  if (pageContent) {
    const hasOwnLayout = pageContent.querySelector(
      ".page-hero, .section, .cta-band, .verse-strip"
    );
    if (!hasOwnLayout) pageContent.classList.add("is-plain");
  }

  /* Library search and filters */
  const librarySearch =
    document.getElementById("librarySearch") ||
    document.querySelector(".library-toolbar input[type='search']");
  const filterButtons = document.querySelectorAll(".filter-btn");
  const libraryGroups = document.querySelectorAll(".lib-group");
  const libraryCards = document.querySelectorAll(".lib-card");
  const resultCount =
    document.getElementById("resultCount") ||
    document.querySelector(".library-results p");
  const emptyState =
    document.getElementById("emptyState") ||
    document.querySelector(".empty-state");

  if (libraryCards.length) {
    let activeFilter = "all";

    const normalize = (value) =>
      value
        .toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .trim();

    const getFilter = (button) => {
      if (button.dataset.filter) return button.dataset.filter;
      const match = button.className.match(/filter-([a-z]+)/);
      return match ? match[1] : "all";
    };

    const getCardCategory = (card) => {
      if (card.dataset.category) return card.dataset.category;
      const group = card.closest(".lib-group");
      return group ? group.dataset.group || group.id || "" : "";
    };

    const getCardTitle = (card) => {
      if (card.dataset.title) return normalize(card.dataset.title);
      const heading = card.querySelector("h3");
      return normalize(heading ? heading.textContent : "");
    };

    const applyLibraryFilter = () => {
      const query = normalize(librarySearch ? librarySearch.value : "");
      let visibleCount = 0;

      libraryGroups.forEach((group) => {
        const groupCards = group.querySelectorAll(".lib-card");
        let visibleInGroup = 0;

        groupCards.forEach((card) => {
          const categoryMatches =
            activeFilter === "all" || getCardCategory(card) === activeFilter;
          const titleMatches = !query || getCardTitle(card).includes(query);
          const show = categoryMatches && titleMatches;

          card.classList.toggle("is-hidden", !show);
          if (show) {
            visibleInGroup += 1;
            visibleCount += 1;
          }
        });

        group.classList.toggle("is-hidden", visibleInGroup === 0);
      });

      if (resultCount) {
        resultCount.textContent = `${visibleCount} ${visibleCount === 1 ? "title" : "titles"}`;
      }

      if (emptyState) {
        emptyState.hidden = visibleCount !== 0;
      }
    };

    filterButtons.forEach((button) => {
      button.addEventListener("click", () => {
        activeFilter = getFilter(button);

        filterButtons.forEach((item) => {
          const isActive = item === button;
          item.classList.toggle("is-active", isActive);
          item.setAttribute("aria-pressed", String(isActive));
        });

        applyLibraryFilter();
      });
    });

    if (librarySearch) {
      librarySearch.addEventListener("input", applyLibraryFilter);
    }

    const applyHashFilter = () => {
      const hashFilter = window.location.hash.replace("#", "");
      if (!["sermons", "books", "videos", "audios"].includes(hashFilter)) return;
      const hashButton = [...filterButtons].find(
        (button) => getFilter(button) === hashFilter
      );
      if (!hashButton) return;

      hashButton.click();

      const target = document.getElementById(hashFilter);
      if (target) {
        target.scrollIntoView({ behavior: "instant", block: "start" });
      }
    };

    applyLibraryFilter();
    applyHashFilter();
    window.addEventListener("hashchange", applyHashFilter);
  }

  /* Contact form — composes a WhatsApp message */
  const contactForm = document.getElementById("whatsappForm");

  if (contactForm) {
    const status = document.getElementById("formStatus");
    const nameField = contactForm.querySelector("#name");
    const messageField = contactForm.querySelector("#message");

    const setStatus = (message, isError = false) => {
      if (!status) return;
      status.textContent = message;
      status.classList.toggle("is-error", isError);
    };

    const markInvalid = (field, invalid) => {
      if (!field) return;
      field.classList.toggle("is-invalid", invalid);
      field.setAttribute("aria-invalid", String(invalid));
    };

    [nameField, messageField].forEach((field) => {
      if (!field) return;
      field.addEventListener("input", () => {
        if (field.value.trim()) markInvalid(field, false);
      });
    });

    contactForm.addEventListener("submit", (event) => {
      event.preventDefault();

      const name = nameField ? nameField.value.trim() : "";
      const subjectField = contactForm.querySelector("#subject");
      const subject = subjectField ? subjectField.value : "General enquiry";
      const message = messageField ? messageField.value.trim() : "";

      if (!name) {
        markInvalid(nameField, true);
        setStatus("Please enter your name so we know who we are speaking with.", true);
        nameField.focus();
        return;
      }

      if (!message) {
        markInvalid(messageField, true);
        setStatus("Please write a short message before sending.", true);
        messageField.focus();
        return;
      }

      markInvalid(nameField, false);
      markInvalid(messageField, false);

      const text = `Hello, my name is ${name}.\n\n${subject}\n\n${message}`;
      const url = `https://wa.me/263775991061?text=${encodeURIComponent(text)}`;
      const opened = window.open(url, "_blank");

      if (!opened) {
        setStatus("Your browser blocked the new window. Allow pop-ups, or call 0775 991 061 directly.", true);
        return;
      }

      opened.opener = null;
      setStatus("WhatsApp is opening with your message ready to send.");
    });
  }
})();

//
